def create_wall(
    *,
    start: Point,
    end: Point,
    base_offset: Optional[Length] = None,
    height: Optional[Length] = None,
    level: Optional[ElementId] = None,
    location_line: Optional[Literal["wall_centerline", "core_centerline", "finish_exterior", "finish_interior"]] = None,
    name: Optional[str] = None,
    top_level: Optional[int] = None,
    top_offset: Optional[Length] = None,
    wall_type: Optional[ElementId] = None,
) -> Dict[str, Any]:
    """Create a straight wall from start to end (z ignored; the base is the level
    elevation + base_offset). The exterior face is on the LEFT of the direction of
    travel, so draw outer walls clockwise seen from above (as in Revit). Height:
    top_level (+ top_offset), else height (default 3 m). Default type "Generic - 200mm".
    Returns {element}.

    Args:
        start: Start. Point [x, y] or [x, y, z] in millimetres (or strings with units);
            Z is up.
        end: End. Point [x, y] or [x, y, z] in millimetres (or strings with units); Z is
            up.
        base_offset: Length: number = millimetres, or a string with units ("3m",
            "300cm"). Optional.
        height: Length: number = millimetres, or a string with units ("3m", "300cm").
            Optional.
        level: Base level id. Optional.
        location_line: One of: wall_centerline, core_centerline, finish_exterior,
            finish_interior. Optional.
        name: Text. Optional.
        top_level: Level the top is attached to. Optional.
        top_offset: Length: number = millimetres, or a string with units ("3m",
            "300cm"). Optional.
        wall_type: Wall type id. Optional.

    Returns:
        The tool's JSON body. Raises FerroError on failure.
    """
    args: Dict[str, Any] = {"start": start, "end": end}
    if base_offset is not None:
        args["base_offset"] = base_offset
    if height is not None:
        args["height"] = height
    if level is not None:
        args["level"] = level
    if location_line is not None:
        args["location_line"] = location_line
    if name is not None:
        args["name"] = name
    if top_level is not None:
        args["top_level"] = top_level
    if top_offset is not None:
        args["top_offset"] = top_offset
    if wall_type is not None:
        args["wall_type"] = wall_type
    return _call("create_wall", args)


def create_walls(
    *,
    points: Sequence[Point],
    base_offset: Optional[Length] = None,
    closed: Optional[bool] = None,
    height: Optional[Length] = None,
    level: Optional[ElementId] = None,
    location_line: Optional[Literal["wall_centerline", "core_centerline", "finish_exterior", "finish_interior"]] = None,
    name: Optional[str] = None,
    top_level: Optional[int] = None,
    top_offset: Optional[Length] = None,
    wall_type: Optional[ElementId] = None,
) -> Dict[str, Any]:
    """Create a chain of walls through points (closed adds the closing wall). Corners
    are mitred automatically. Returns {elements}.

    Args:
        points: List of points [x, y, z] in millimetres. Each: Vertex. minItems=2.
        base_offset: Length: number = millimetres, or a string with units ("3m",
            "300cm"). Optional.
        closed: True or False. Optional.
        height: Length: number = millimetres, or a string with units ("3m", "300cm").
            Optional.
        level: Base level id. Optional.
        location_line: One of: wall_centerline, core_centerline, finish_exterior,
            finish_interior. Optional.
        name: Text. Optional.
        top_level: Level the top is attached to. Optional.
        top_offset: Length: number = millimetres, or a string with units ("3m",
            "300cm"). Optional.
        wall_type: Wall type id. Optional.

    Returns:
        The tool's JSON body. Raises FerroError on failure.
    """
    args: Dict[str, Any] = {"points": points}
    if base_offset is not None:
        args["base_offset"] = base_offset
    if closed is not None:
        args["closed"] = closed
    if height is not None:
        args["height"] = height
    if level is not None:
        args["level"] = level
    if location_line is not None:
        args["location_line"] = location_line
    if name is not None:
        args["name"] = name
    if top_level is not None:
        args["top_level"] = top_level
    if top_offset is not None:
        args["top_offset"] = top_offset
    if wall_type is not None:
        args["wall_type"] = wall_type
    return _call("create_walls", args)


